{
  "ready": true,
  "brief": "A calm, sunlit scene in a modern Austin office setting, showing a relaxed professional or weekend athlete receiving a gentle, professional posture assessment from a board-certified chiropractor. The visual mood is warm, trustworthy, and unhurried, avoiding any sense of urgency or high-pressure sales. The copy leads with the specific offer: '$49 new-patient exam and consultation,' clearly stating that same-day appointments are available. The tone is plain-spoken and professional, emphasizing the value of the digital posture scan included in the visit and the clinic's transparent approach to care. No exclamation marks or hype, just a clear, accessible invitation for adults in the Austin area to prioritize their spinal health with a low-barrier first step.",
  "language": "en",
  "angleId": "value",
  "recommendations": [
    {
      "label": "Problem-Solution Focus",
      "prompt": "Create a variation that leads with the specific pain point of desk-job neck and back stiffness, positioning the $49 exam as the direct solution to find the root cause, rather than just a price point."
    },
    {
      "label": "Trust & Experience Focus",
      "prompt": "Create a variation that leads with the '15+ years combined experience' and 'Board-certified' credentials to build trust, using the $49 exam as a low-risk way to experience that expertise, targeting skeptical new patients."
    }
  ]
}

